use vstd::prelude::*;

verus! {

fn hermemulx(c: Vec<f64>) -> (result: Vec<f64>)
    requires
        c.len() < usize::MAX,
    ensures
        result.len() == c.len() + 1,
        result[0] == 0.0,
        forall|i: int|
            1 <= i && i < c.len() as int
            ==> result[(i + 1) as int] == c[i],
{
    let n: usize = c.len();

    // Allocate result with length n+1 filled with 0.0
    let mut result: Vec<f64> = vec![0.0; n + 1];

    let mut i: usize = 1;
    while i < n
        invariant
            n == c.len(),
            result.len() == n + 1,
            result[0] == 0.0,
            1 <= i && i <= n,
            forall|k: int|
                1 <= k && k < i as int
                ==> result[(k + 1) as int] == c[k],
        decreases n - i,
    {
        result.set(i + 1, c[i]);
        i = i + 1;
    }

    result
}

} // verus!

